practice-constructors:
#include <iostream>

class Account {
    int balance_;
public:
    explicit Account(int initial) : balance_{initial} {}
    void withdraw(int amount) { if(amount <= balance_) balance_ -= amount; }
    int balance() const { return balance_; }
};

int main() {
    int initial{}, amount{}; std::cin >> initial >> amount;
    Account a{initial}; a.withdraw(amount); std::cout << a.balance() << "\n";
}

practice-polymorphism:
#include <iostream>
#include <string>

struct Shape { virtual int area() const = 0; virtual ~Shape() = default; };
struct Square : Shape { int w; explicit Square(int x): w{x} {} int area() const override { return w*w; } };
struct Rectangle : Shape { int w,h; Rectangle(int x,int y): w{x},h{y} {} int area() const override { return w*h; } };

int main() {
    std::string kind; int w{}, h{}; std::cin >> kind >> w >> h;
    Square s{w}; Rectangle r{w,h};
    const Shape& shape = kind == "square" ? static_cast<const Shape&>(s) : static_cast<const Shape&>(r);
    std::cout << shape.area() << "\n";
}

